async reply(messages: ChatTurnDto[]): Promise<{ reply: string }> {
    (1) const { enabled, model } = this.config.chat;
    (2) if (!enabled) throw new ServiceUnavailableException(UNAVAILABLE);
    (3) this.validate(messages);

    const animals = await this.prisma.animal.findMany({
        where: { deletedAt: null, status: 'DISPONIBLE_ADOPCION' },
        select: {
            name: true,
            code: true,
            species: true,
            size: true,
            ageMonths: true,
            goodWithChildren: true,
            goodWithAnimals: true,
        },
        orderBy: { code: 'asc' },
        take: 40,
    });

    try {
        (4) const response = await this.getClient().beta.messages.create({
            model,
            max_tokens: 16000,
            output_config: { effort: 'low' },
            (5) ...(FALLBACK_MODELS.has(model)
                (6) ? { betas: ['server-side-fallback-2026-07-01'], fallbacks: 'default' as const }
                (7) : {}),
            (8) system: [
                {
                    type: 'text',
                    text: stableSystemPrompt(this.config.institution),
                    cache_control: { type: 'ephemeral' },
                },
                { type: 'text', text: adoptablesPrompt(animals) },
            ],
            messages: messages.map((m) => ({ role: m.role, content: m.content })),
        });

        (9) if (response.stop_reason === 'refusal') return { reply: REFUSAL_REPLY };

        (10) const text = response.content
            .filter((b): b is Anthropic.Beta.BetaTextBlock => b.type === 'text')
            .map((b) => b.text)
            .join('\n')
            .trim();
        (11) return { reply: text ||
            (12) REFUSAL_REPLY };
    } catch (err) {
        (13) if (err instanceof Anthropic.RateLimitError) {
            (14) throw new ServiceUnavailableException(
                'El asistente está muy ocupado. Intenta en unos segundos.',
            );
        }
        (15) if (err instanceof Anthropic.AuthenticationError) {
            (16) this.logger.error('ANTHROPIC_API_KEY inválida');
            throw new ServiceUnavailableException(UNAVAILABLE);
        }
        (17) if (err instanceof Anthropic.APIError) {
            (18) this.logger.error(`Error de la API de Claude (${err.status}): ${err.message}`);
            throw new ServiceUnavailableException(UNAVAILABLE);
        }
        (19) throw err;
    }
}

